function TabPanel({ children, value, index }) {
  return (
    <div hidden={value !== index} className="tab-panel">
      {value === index && (
        <Box sx={{ p: 3 }}>
          <Typography>{children}</Typography>
        </Box>
      )}
    </div>
  );
}

