function HostelMenu() {
  const [selectedDay, setSelectedDay] = useState(null);
  const [tabValue, setTabValue] = useState(0);
  const [menuType, setMenuType] = useState('tamil'); // 'tamil' or 'international'

  const handleDayClick = (day, meals) => {
    setSelectedDay({ day, meals });
    setTabValue(0);
  };

  const handleClose = () => {
    setSelectedDay(null);
  };

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  return (
    <>
      <Paper elevation={3} className="menu-container">
        <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Typography variant="h5" component="h2">
            Weekly Hostel Menu
          </Typography>
          <Box>
            <Tabs value={menuType} onChange={(e, newValue) => setMenuType(newValue)}>
              <Tab 
                value="tamil" 
                label="Tamil Menu" 
                sx={{ '&.Mui-selected': { color: '#4caf50' } }}
              />
              <Tab 
                value="international" 
                label="International Menu" 
                sx={{ '&.Mui-selected': { color: '#2196f3' } }}
              />
            </Tabs>
          </Box>
        </Box>
        <Grid container spacing={3}>
          {Object.entries(menuType === 'tamil' ? tamilMenu : internationalMenu).map(([day, meals]) => (
            <Grid item xs={12} sm={6} md={4} key={day}>
              <Card 
                className="day-card" 
                onClick={() => handleDayClick(day, meals)}
                sx={{ cursor: 'pointer' }}
              >
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    {day}
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    Click to view detailed menu
                  </Typography>
                  <RestaurantIcon sx={{ mt: 2, color: 'primary.main' }} />
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Paper>

      <Dialog 
        open={Boolean(selectedDay)} 
        onClose={handleClose}
        maxWidth="sm"
        fullWidth
      >
        {selectedDay && (
          <>
            <DialogTitle sx={{ m: 0, p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <Typography variant="h6">{selectedDay.day}'s Menu</Typography>
              <IconButton
                aria-label="close"
                onClick={handleClose}
                sx={{
                  color: (theme) => theme.palette.grey[500],
                  '&:hover': {
                    color: (theme) => theme.palette.primary.main,
                  },
                }}
              >
                <CloseIcon />
              </IconButton>
            </DialogTitle>
            <DialogContent>
              <Tabs 
                value={tabValue} 
                onChange={handleTabChange}
                variant="fullWidth"
                sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}
              >
                <Tab 
                  icon={<FreeBreakfastIcon />} 
                  label="Breakfast" 
                  sx={{ '&.Mui-selected': { color: '#ff9800' } }}
                />
                <Tab 
                  icon={<LunchDiningIcon />} 
                  label="Lunch"
                  sx={{ '&.Mui-selected': { color: '#4caf50' } }}
                />
                <Tab 
                  icon={<DinnerDiningIcon />} 
                  label="Dinner"
                  sx={{ '&.Mui-selected': { color: '#2196f3' } }}
                />
              </Tabs>
              
              <TabPanel value={tabValue} index={0}>
                <Typography variant="h6" color="#ff9800" gutterBottom>
                  Breakfast
                </Typography>
                {selectedDay.meals.breakfast}
              </TabPanel>
              
              <TabPanel value={tabValue} index={1}>
                <Typography variant="h6" color="#4caf50" gutterBottom>
                  Lunch
                </Typography>
                {selectedDay.meals.lunch}
              </TabPanel>
              
              <TabPanel value={tabValue} index={2}>
                <Typography variant="h6" color="#2196f3" gutterBottom>
                  Dinner
                </Typography>
                {selectedDay.meals.dinner}
              </TabPanel>
            </DialogContent>
          </>
        )}
      </Dialog>
    </>
  );
}

export default HostelMenu;
